'use strict';
const {sectors,questions}=DMA_DATA;
const E=DMAEngine;
const icon=name=>DMAIcons[name]||'';
const KEY='digitala-mognadsresan-v1';
const main=document.getElementById('main');
let answers={},saveEnabled=false,storageAvailable=true,currentIndex=0,screen='map',demo=false,draft=null,noneSelected=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1){answers=E.cleanAnswers(saved.answers);saveEnabled=true;}}catch{storageAvailable=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sectorFor=q=>sectors.find(s=>s.questions.includes(q.id));
const sectorComplete=s=>s.questions.every(id=>E.validAnswer(E.byId[id],answers[id]));
const done=s=>s.questions.filter(id=>E.validAnswer(E.byId[id],answers[id])).length;
function persist(){if(!saveEnabled)return;try{localStorage.setItem(KEY,JSON.stringify({version:1,answers}));}catch{storageAvailable=false;saveEnabled=false;toast('Webbläsaren kunde inte spara. Svaren finns kvar tills fliken stängs.');}}
function focusMain(){window.scrollTo(0,0);main.focus({preventScroll:true});}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function modal(html){document.getElementById('dialog-content').innerHTML=html;document.getElementById('dialog').showModal();}
function celebrate(){document.querySelector('.complete-card')?.classList.add('mission-unlocked');}
function radar(values,empty=false){
 const cx=270,cy=222,r=132;
 const point=(i,v)=>{const a=(-90+i*60)*Math.PI/180;return [cx+Math.cos(a)*r*v/100,cy+Math.sin(a)*r*v/100];};
 const points=v=>sectors.map((_,i)=>point(i,typeof v==='number'?v:v[i]??0).join(',')).join(' ');
 const labels=[['Strategi',270,54],['Teknik',462,137],['Människor',463,309],['Data',270,395],['AI',80,309],['Hållbarhet',79,137]];
 return `<svg class="radar" viewBox="0 0 540 430" role="img" aria-label="${empty?'Sex områden att utforska. Ingen bedömning ännu.':esc('Spindeldiagram: '+sectors.map((s,i)=>s.short+' '+(values[i]===null?'ej bedömd':Math.round(values[i])+' av 100')).join(', '))}"><title>${empty?'Din digitala profil växer fram när du spelar':'Digital mognad per område'}</title>${[25,50,75,100].map(v=>`<polygon class="radar-grid" points="${points(v)}"/>`).join('')}${sectors.map((_,i)=>`<line class="radar-grid" x1="${cx}" y1="${cy}" x2="${point(i,100)[0]}" y2="${point(i,100)[1]}"/>`).join('')}${empty?`<circle cx="${cx}" cy="${cy}" r="37" fill="#4698CA" fill-opacity=".08" stroke="#4698CA" stroke-dasharray="3 5"/><text x="${cx}" y="${cy+6}" text-anchor="middle" style="fill:var(--accent);font-size:20px">?</text>`:`<polygon class="radar-data" points="${points(values)}"/>${values.map((v,i)=>v===null?'':`<circle class="radar-dot" r="4" cx="${point(i,v)[0]}" cy="${point(i,v)[1]}"/>`).join('')}`}${[25,50,75,100].map(v=>`<text x="${cx+7}" y="${cy-r*v/100-3}" style="font-size:10px">${v}</text>`).join('')}${labels.map(([s,x,y],i)=>`<text class="axis-label" text-anchor="middle" x="${x}" y="${y}">${s}</text>${!empty?`<text class="score-label" text-anchor="middle" x="${x}" y="${y+19}">${values[i]===null?'–':Math.round(values[i])+' %'}</text>`:''}`).join('')}</svg>`;
}
function renderMap(){
 screen='map';demo=false;const p=E.progress(answers),s=E.scores(answers),all=p.completed===p.total;
 main.innerHTML=`<div class="intro-grid"><section class="intro-copy"><div class="eyebrow">Techtank / Digitala Mognadsresan</div><h1>Sex uppdrag.<br>En tydligare<br><span>digital framtid.</span></h1><p>Hur redo är ni för nästa steg? Utforska sex områden, samla insikter och lås upp er digitala mognadsprofil.</p><div class="intro-stats"><div><b>6 uppdrag</b><span>En gemensam riktning</span></div><div><b>86 delar</b><span>11 frågeomgångar</span></div><div><b>20–30 min</b><span>Spela i er egen takt</span></div></div><div class="action-row"><button class="button" data-action="${all?'report':'start'}">${all?'Visa er mognadsprofil':p.completed?'Fortsätt resan':'Starta resan'} ${icon('arrow-up-right')}</button><button class="text-button" data-action="demo">Se en exempelrapport</button></div><p class="microcopy">Inget konto krävs. Era svar stannar på enheten.</p></section><section class="radar-panel"><div class="panel-heading">Er digitala kompass</div>${radar(s.sectors.map(x=>x.score),p.sectorDone===0)}<div class="radar-caption">${p.sectorDone?`${p.sectorDone} av 6 områden kartlagda · obesvarat visas som –`:'Slutför uppdragen för att rita er profil'}</div></section></div><div class="expedition-bar"><span class="xp">${icon('star')} ${p.xp} / 1 400 XP</span><div class="mini-progress" role="progressbar" aria-label="Besvarade frågeomgångar" aria-valuenow="${p.completed}" aria-valuemin="0" aria-valuemax="11"><span style="width:${p.percent}%"></span></div><span class="bar-label">${p.completed} av 11 omgångar klara</span><span class="xp">${p.percent}%</span></div><div class="section-heading"><h2>Välj ditt nästa uppdrag</h2><p>Alla områden är öppna.</p></div><div class="mission-grid">${sectors.map((s,i)=>`<button class="mission-card ${!p.completed&&i===0?'active':''}" data-sector="${i}" style="--sector:${s.color}"><div class="card-top"><span class="sector-icon" aria-hidden="true">${icon(s.icon)}</span><span class="sector-number">UPPDRAG 0${i+1} ${sectorComplete(s)?icon('check'):''}</span></div><h3>${s.name}</h3><p>${s.description}</p><div class="card-bottom"><span>${sectorComplete(s)?s.badge:done(s)+' / '+s.questions.length+' omgångar'}</span><span class="card-arrow">${icon('arrow-up-right')}</span></div><div class="mini-progress"><span style="width:${done(s)/s.questions.length*100}%"></span></div></button>`).join('')}</div><div class="local-controls"><label class="save-choice"><input id="save-progress" type="checkbox" ${saveEnabled?'checked':''}> Spara bekräftade svar i den här webbläsaren</label><p class="storage-status">${saveEnabled?'Sparas på enheten tills du raderar dem. Undvik detta på en delad dator.':'Svaren finns bara i den här fliken. Stänger du fliken försvinner de.'}${!storageAvailable?' Lokal lagring är inte tillgänglig.':''}</p>${p.completed?'<button class="text-button" data-action="reset">Radera svar och börja om</button>':''}</div>`;
}
function openQuestion(index){
 currentIndex=Math.max(0,Math.min(questions.length-1,index));screen='question';demo=false;const q=questions[currentIndex];draft=answers[q.id]?[...answers[q.id].values]:q.type==='multi'?[]:Array(q.items.length).fill(null);noneSelected=q.type==='multi'&&!!answers[q.id]&&draft.length===0;renderQuestion();focusMain();
}
function renderQuestion(){
 const q=questions[currentIndex],s=sectorFor(q),sn=sectors.indexOf(s),p=E.progress(answers);
 const hint=q.type==='multi'?'Markera allt som stämmer i dag. Välj ”Inget av alternativen” om inget stämmer.':q.type==='investment'?'Skilj på vad ni redan har gjort och vad ni planerar. Framtidsplaner höjer inte nulägespoängen.':'Välj ett svar för varje rad. Utgå från hur det faktiskt ser ut i verksamheten i dag.';
 main.innerHTML=`<div class="workspace"><aside class="side-nav"><button class="back-link" data-action="map">${icon('arrow-left')} Uppdragskartan</button><h2>Din expedition</h2><p>${p.completed} av 11 omgångar · ${p.xp} XP</p><nav aria-label="Uppdrag">${sectors.map((a,i)=>`<button class="nav-sector ${a===s?'current':''}" data-sector="${i}" style="--sector:${a.color}" ${a===s?'aria-current="step"':''}><span aria-hidden="true">${icon(a.icon)}</span><span>${a.short}</span><span>${sectorComplete(a)?icon('check'):done(a)+'/'+a.questions.length}</span></button>`).join('')}</nav><div class="privacy-note">Du får XP för att slutföra uppdrag, oavsett vilka svar du väljer. Ett ärligt nuläge är den bästa starten.</div></aside><section class="question-area"><div class="question-topline"><span class="eyebrow" style="color:${s.color}">Uppdrag 0${sn+1} / ${s.name}</span><span>${s.questions.indexOf(q.id)+1} av ${s.questions.length}</span></div><div class="mini-progress" style="--sector:${s.color}"><span style="width:${(s.questions.indexOf(q.id)+1)/s.questions.length*100}%"></span></div><h1 class="question-title">${esc(q.prompt)}</h1><p class="question-hint">${hint}</p><form id="answer-form" novalidate>${q.type==='multi'?`<div class="answer-list">${q.items.map((item,i)=>`<label class="answer-option"><input type="checkbox" name="answer" value="${i}" ${draft.includes(i)?'checked':''}><span>${esc(item)}</span></label>`).join('')}<label class="answer-option none-option"><input type="checkbox" name="none" ${noneSelected?'checked':''}><span>Inget av alternativen stämmer</span></label></div>`:`<div class="matrix">${q.items.map((item,i)=>`<div class="matrix-row"><label for="item-${i}">${esc(item)}${q.id==='q4'&&i===6?'<span class="item-help">Avser additiv tillverkning, exempelvis 3D-utskrift.</span>':''}</label><select id="item-${i}" name="item-${i}" data-item="${i}" required><option value="">Välj nuläge…</option>${q.labels.map((label,j)=>`<option value="${j}" ${draft[i]===j?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`).join('')}</div>`}<p id="validation" class="validation" role="alert"></p><div class="question-actions"><button type="button" class="button ghost" data-action="previous">${icon('arrow-left')} Tillbaka</button><div><button type="button" class="button ghost" data-action="later">Ta senare</button><button type="submit" class="button">${currentIndex===questions.length-1?'Slutför':'Bekräfta'} ${icon('arrow-right')}</button></div></div></form><p class="question-counter">Frågeomgång ${q.number} av 11 · ${q.items.length} delar${saveEnabled?' · Bekräftade svar sparas lokalt':''}</p></section></div>`;
}
function confirmAnswer(){
 const q=questions[currentIndex];
 if(q.type==='multi'&&!draft.length&&!noneSelected){document.getElementById('validation').textContent='Välj minst ett alternativ, eller markera att inget stämmer.';return false;}
 const a={confirmed:true,values:draft};
 if(!E.validAnswer(q,a)){document.getElementById('validation').textContent='Välj ett nuläge på varje rad innan du fortsätter.';document.querySelector('select:invalid')?.focus();return false;}
 const s=sectorFor(q),wasComplete=sectorComplete(s),wasAnswered=!!answers[q.id];answers[q.id]={confirmed:true,values:[...draft]};persist();
 if(!wasComplete&&sectorComplete(s)){renderComplete(s);celebrate();}else if(E.progress(answers).completed===questions.length){renderReport(false);if(!wasAnswered)celebrate();}else{toast(wasAnswered?'Svaret är uppdaterat':'Omgång klar! +100 XP');const next=questions.findIndex((x,i)=>i>currentIndex&&!answers[x.id]);if(next>=0)openQuestion(next);else renderMap();}
 return true;
}
function renderComplete(s){
 screen='complete';const p=E.progress(answers),all=p.completed===p.total;
 main.innerHTML=`<section class="complete-card"><div class="complete-icon" aria-hidden="true">${icon(s.icon)}</div><div class="badge">${icon('check')} ${s.badge}</div><h1>${all?'Hela kartan är er.':'Ett steg närmare.'}</h1><p>Ni har kartlagt <strong>${s.name.toLowerCase()}</strong> och fått märket ${s.badge}. ${all?'Alla sex uppdrag är klara. Nu väntar er mognadsprofil och nästa steg.':'Varje ärligt svar gör nästa beslut lite tydligare.'}</p><div class="xp">+100 XP för omgången · +50 XP för uppdraget</div><div class="action-row" style="margin-top:28px"><button class="button" data-action="${all?'report':'start'}">${all?'Lås upp er rapport':'Nästa uppdrag'} ${icon('arrow-right')}</button><button class="button ghost" data-action="map">Till kartan</button></div><p class="microcopy">${p.sectorDone} av 6 märken · ${p.xp} XP</p></section>`;focusMain();
}
const reportText=DMAReport.text;
function renderReport(isDemo){
 demo=isDemo;screen='report';const source=demo?E.demoAnswers():answers;
 if(E.scores(source).overall===null){toast('Slutför alla 11 omgångar för att låsa upp rapporten.');renderMap();return;}
 const {scores,level,summary,securityGap,priorities}=DMAReport.create(source,{demo});
 main.innerHTML=`${demo?'<div class="demo-banner"><strong>Fiktivt exempel.</strong> Alla svar i denna rapport är konstruerade. Dina egna svar påverkas inte.</div>':''}<button class="back-link" data-action="map">${icon('arrow-left')} Till uppdragskartan</button><div class="report-header"><div><div class="eyebrow">${demo?'En möjlig slutbild':'6 uppdrag klara · 1 400 XP'}</div><h1>Er digitala mognadsprofil.</h1><p>Från nuläge till nästa kloka steg. PDF:en innehåller även alla era svar.</p></div><div class="action-row"><button class="button small" data-action="pdf">Ladda ner PDF</button><button class="button small secondary" data-action="print">Skriv ut</button></div></div><div class="report-grid"><section class="report-card"><h2>Sex perspektiv på er verksamhet</h2>${radar(scores.sectors.map(s=>s.score))}<p class="microcopy">Varje axel visar 0–100. Detta är spelets egen poängmodell.</p></section><section class="report-card"><div class="eyebrow">Samlad självskattning</div><div class="score-display">${Math.round(scores.overall)}<small> / 100</small></div><h2>${level}</h2><p style="margin-top:14px">${summary}</p><div class="score-bars">${scores.sectors.map(s=>`<div><div class="score-bar-title"><span>${s.name}</span><b>${Math.round(s.score)}%</b></div><div class="mini-progress" style="--sector:${s.color}"><span style="width:${s.score}%"></span></div></div>`).join('')}</div></section></div>${securityGap?'<div class="report-note"><strong>Prioritera kontinuitet.</strong> Säkerhetskopiering eller kontinuitetsplan saknas bland era val. Kontrollera detta tidigt, även om den samlade poängen är hög.</div>':''}<section class="report-section"><h2>Det här berättar era svar</h2><p>Reflektioner utifrån självskattningen, med ett konkret nästa steg per område.</p><div class="insight-grid" style="margin-top:20px">${scores.sectors.map(s=>{const t=reportText(s);return `<article class="insight"><div class="insight-score">${Math.round(s.score)} / 100 · ${E.level(s.score)}</div><h3>${s.name}</h3><p>${t.summary}</p><p class="next-step"><strong>Nästa steg:</strong> ${t.action}</p></article>`;}).join('')}</div></section><section class="report-section"><h2>Gör insikten till handling</h2><p>Ett förslag för de kommande 90 dagarna. Anpassa ordningen efter behov, risk och resurser.</p><div class="roadmap">${priorities.map((s,i)=>`<article class="roadmap-item"><small>${['DAG 1–30 · FÖRSTÅ','DAG 31–60 · PRÖVA','DAG 61–90 · FÖLJ UPP'][i]}</small><h3>${s.name}</h3><p>${reportText(s).action}</p><p style="margin-top:14px">${['Utse en ansvarig och beskriv hur ni ser att det blir bättre.','Gör ett litet, avgränsat försök och dokumentera vad ni lär er.','Jämför med nuläget och besluta om ni ska justera, skala upp eller avsluta.'][i]}</p></article>`).join('')}</div></section><div class="report-note"><strong>Om resultatet:</strong> Baserat på 11 frågeomgångar och 86 delar i det tillhandahållna DMA-underlaget. Detta är en vägledande självskattning med en egen, transparent spelmodell. Den är inte ett officiellt EU DMAT-resultat, en certifiering eller en säkerhetsrevision. Teknikernas relevans varierar mellan verksamheter; ett lågt teknikvärde behöver inte innebära låg affärsförmåga. <button class="text-button" data-action="method">Läs hur poängen räknas</button></div>${contactPanel()}<div class="action-row" style="margin-top:26px"><button class="button secondary" data-action="map">${demo?'Starta er egen resa':'Granska och ändra svar'}</button><button class="text-button" data-action="share">Kopiera länk till spelet</button></div>`;focusMain();
}
function contactPanel(){
 const c=DMAContact;
 const projectLink=`<a class="project-link" href="${c.projectUrl}" target="_blank" rel="noopener noreferrer">${esc(c.projectName)}</a>`;
 return `<section class="contact-panel" aria-labelledby="contact-heading"><div><div class="eyebrow">Ert nästa steg</div><h2 id="contact-heading">Låt oss gå igenom er DMA tillsammans.</h2><p>Boka ett kostnadsfritt samtal om er digitala mognadsanalys och hur ${projectLink} kan hjälpa er vidare med digitalisering och implementering av generativ AI.</p><p class="contact-identity"><strong>${esc(c.name)}</strong><br>${esc(c.role)} för ${projectLink} hos ${esc(c.organisation)}</p><p class="contact-details"><a href="mailto:${c.email}">${esc(c.email)}</a><br><a href="tel:${c.phoneLink}">${esc(c.phone)}</a></p></div><div class="contact-action"><a class="button" href="mailto:${c.email}?subject=${encodeURIComponent(c.subject)}">Boka via e-post ${icon('arrow-up-right')}</a><p>Föreslå en tid som passar er. Du väljer själv om du vill bifoga rapporten. Inga svar skickas automatiskt.</p></div><div class="funding-logos"><img src="assets/brand/digit-hub-eu-sv.png" alt="DigIT Hub. Medfinansieras av Europeiska unionen." width="1366" height="768" loading="lazy"></div></section>`;
}
function showMethod(){modal(`<div class="eyebrow">Öppet om modellen</div><h2>Metod & integritet</h2><p>Frågorna speglar <em>EU:s Digital Maturity Assessment Tool (DMAT) för SME</em>. De 11 frågeomgångarna och alla 86 delar finns med. Formuleringarna är bevarade; svarsalternativen för investeringar har samlats i fyra kombinationer.</p><h3>Så räknas resultatet</h3><ul><li>Flervalsfrågor: andel markerade positiva alternativ × 100. ”Inget” ger 0.</li><li>Affärsområden: andel områden där ni redan har investerat × 100. Planer ger inga nulägespoäng.</li><li>Skalor 0–5 och Nej/Delvis/Ja: medelvärdet räknas om till 0–100. Nej = 0, Delvis = 50, Ja = 100.</li><li>Datahantering: ”Uppgifter samlas inte in digitalt” ger 0 och kan inte kombineras med digitala arbetssätt. En policy kan ändå finnas. I övrigt räknas andelen av de sju positiva alternativen.</li><li>Sex områden: strategi (fråga 1–2), teknik (3–4), människor (5–6), data (7–8), automatisering (9), hållbarhet (10–11). Frågorna väger lika inom varje område. Totalen är medelvärdet av de sex områdena, före avrundning.</li></ul><p>Spelets fyra nivåer är 0–&lt;25, 25–&lt;50, 50–&lt;75 och 75–100. De är egna spelbenämningar. XP och märken belönar slutförande och påverkar aldrig mognadspoängen.</p><p>Ingen officiell poängnyckel följde med underlaget. Resultatet ska därför inte jämföras direkt med EU DMAT-poäng. Alla uppräknade tekniker är inte relevanta för alla företag. Rapporten genereras med fasta, lokala regler.</p><h3>Era svar stannar på enheten</h3><p>Spelet begär inga namn, kontaktuppgifter eller företagsuppgifter. Det skickar inga svar till en server, använder inga externa AI-tjänster och har inga analysverktyg eller externa teckensnitt. Webbvärden kan behandla vanliga besöksuppgifter när sidan laddas.</p><p>Svar finns i flikens minne. Om du väljer lokal lagring sparas bekräftade svar i webbläsaren tills du raderar dem. Nedladdade rapporter innehåller er bedömning och samtliga svar: förvara dem enligt era rutiner. Att kopiera spellänken delar inga svar. Kontaktlänken öppnar ditt e-postprogram utan att bifoga svar eller rapport. Du väljer själv vad du skriver, bifogar och skickar.</p><p>Exempelrapporten använder endast konstruerade svar. Underlagets konfidentiella exempel ingår inte i spelet.</p><button class="button secondary" data-action="close">Tillbaka till spelet</button>`);}
function showHelp(){modal(`<div class="eyebrow">Så spelar ni</div><h2>En expedition, sex uppdrag.</h2><p>Samla gärna personer från olika delar av företaget. Svara utifrån dagens arbetssätt och prata om det ni är osäkra på.</p><ul><li>Välj ett uppdrag och besvara frågeomgångarna. Alla områden är öppna.</li><li>Bekräfta varje omgång för att få 100 XP. Ett färdigt uppdrag ger ett märke och 50 XP extra.</li><li>Ni kan ta en fråga senare och återvända från kartan. Obekräftade val sparas inte.</li><li>Efter alla 11 omgångar får ni ett spindeldiagram, en skriven bedömning och förslag till nästa steg.</li></ul><p>Det finns inga rätta eller felaktiga nulägen. Ett lågt värde kan vara början på ett bra samtal.</p><button class="button" data-action="close">Redo att utforska</button>`);}
let pdfBusy=false;
async function downloadPdf(){
 if(pdfBusy)return;pdfBusy=true;
 const button=document.querySelector('[data-action="pdf"]');if(button){button.disabled=true;button.textContent='Skapar PDF…';}
 try{
  const model=DMAReport.create(demo?E.demoAnswers():answers,{demo});
  const bytes=await DMAPdf.generate(model);
  const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
  const a=document.createElement('a');a.href=url;a.download=model.demo?'mognadsprofil-fiktivt-exempel.pdf':'digital-mognadsprofil.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);
  toast('PDF-rapporten är klar. Ingen kopia har skickats till någon annan.');
 }catch{toast('PDF-filen kunde inte skapas. Försök igen eller använd Skriv ut.');}
 finally{pdfBusy=false;if(button){button.disabled=false;button.textContent='Ladda ner PDF';}}
}
function nextUnanswered(){return questions.findIndex(q=>!E.validAnswer(q,answers[q.id]));}
function dispatch(action){
 if(action==='map'){renderMap();focusMain();}
 if(action==='start'){const i=nextUnanswered();i<0?renderReport(false):openQuestion(i);}
 if(action==='demo')renderReport(true);
 if(action==='report')renderReport(false);
 if(action==='previous')currentIndex?openQuestion(currentIndex-1):(renderMap(),focusMain());
 if(action==='later'){if(currentIndex<questions.length-1)openQuestion(currentIndex+1);else{renderMap();focusMain();}toast('Du kan återvända till omgången från uppdragskartan.');}
 if(action==='method')showMethod();
 if(action==='close')document.getElementById('dialog').close();
 if(action==='print')window.print();
 if(action==='pdf')downloadPdf();
 if(action==='share'){const link=location.protocol==='file:'?'https://ponddigger.github.io/digital-maturity-quest/':location.href.split('#')[0].split('?')[0];if(navigator.clipboard)navigator.clipboard.writeText(link).then(()=>toast('Spellänken är kopierad. Inga svar följer med.')).catch(()=>modal(`<h2>Länk till spelet</h2><p>${esc(link)}</p>`));else modal(`<h2>Länk till spelet</h2><p>${esc(link)}</p>`);}
 if(action==='reset')modal('<h2>Radera era svar?</h2><p>Alla svar, XP och märken tas bort från spelet och denna webbläsare. Rapporter som redan laddats ner påverkas inte.</p><div class="action-row"><button class="button" data-action="confirm-reset">Radera och börja om</button><button class="button secondary" data-action="close">Behåll svaren</button></div>');
 if(action==='confirm-reset'){answers={};saveEnabled=false;try{localStorage.removeItem(KEY);}catch{toast('Lokal lagring kunde inte nås. Rensa webbplatsdata i webbläsaren.');}document.getElementById('dialog').close();renderMap();focusMain();}
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action],[data-sector]');if(!b)return;if(b.dataset.action)dispatch(b.dataset.action);if(b.dataset.sector!==undefined){const s=sectors[Number(b.dataset.sector)];const id=s.questions.find(id=>!answers[id])||s.questions[0];openQuestion(questions.findIndex(q=>q.id===id));}});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='save-progress'){saveEnabled=el.checked;if(saveEnabled)persist();else try{localStorage.removeItem(KEY);}catch{toast('Kunde inte radera lokal lagring. Rensa webbplatsdata i webbläsaren.');}renderMap();return;}
 if(screen!=='question')return;const q=questions[currentIndex];
 if(el.name==='answer'){
 const value=Number(el.value);if(el.checked){noneSelected=false;draft.push(value);if(q.exclusive!==undefined){if(value===q.exclusive)draft=draft.filter(v=>v<=q.exclusive);else if(value>q.exclusive)draft=draft.filter(v=>v!==q.exclusive);}}else draft=draft.filter(v=>v!==value);
 document.querySelectorAll('input[name="answer"]').forEach(box=>box.checked=draft.includes(Number(box.value)));document.querySelector('input[name="none"]').checked=false;
 }
 if(el.name==='none'){noneSelected=el.checked;if(noneSelected){draft=[];document.querySelectorAll('input[name="answer"]').forEach(box=>box.checked=false);}}
 if(el.dataset.item!==undefined)draft[Number(el.dataset.item)]=el.value===''?null:Number(el.value);
 document.getElementById('validation').textContent='';
});
document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();confirmAnswer();}});
document.getElementById('method').addEventListener('click',showMethod);
document.getElementById('help').addEventListener('click',showHelp);
document.querySelector('.dialog-close').addEventListener('click',()=>document.getElementById('dialog').close());
renderMap();
// Optional WebMCP interface. It operates on the same local state as the visible game.
const context=document.modelContext;
if(context?.registerTool){
 const tools=[
  {name:'read_assessment_status',title:'Läs spelstatus',description:'Read local completion and XP. Does not return individual company answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw new Error('No arguments expected.');return {...E.progress(answers),missing:questions.filter(q=>!answers[q.id]).map(q=>q.id)};}},
  {name:'open_assessment_question',title:'Öppna en frågeomgång',description:'Navigate to a local question group without changing confirmed answers. Unconfirmed choices are discarded.',inputSchema:{type:'object',properties:{questionId:{type:'string',enum:questions.map(q=>q.id)}},required:['questionId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='questionId')||!E.byId[input.questionId])throw new Error('Unknown question.');openQuestion(questions.findIndex(q=>q.id===input.questionId));return {questionId:input.questionId,opened:true};}},
  {name:'confirm_assessment_answer',title:'Bekräfta svar',description:'Confirm answers for one question group on this device, update XP and the visible game. Multi-select values are zero-based item indexes; an empty array explicitly means none. For scales/investments provide one zero-based option index for every row. Saves locally only if the player enabled local saving.',inputSchema:{type:'object',properties:{questionId:{type:'string',enum:questions.map(q=>q.id)},values:{type:'array',items:{type:'integer',minimum:0}}},required:['questionId','values'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>!['questionId','values'].includes(k))||!E.validAnswer(E.byId[input.questionId],{confirmed:true,values:input.values}))throw new Error('Invalid or contradictory answers. Nothing changed.');openQuestion(questions.findIndex(q=>q.id===input.questionId));draft=[...input.values];noneSelected=draft.length===0;confirmAnswer();return {confirmed:input.questionId,...E.progress(answers)};}}
 ];
 for(const tool of tools)try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}
}
